/**
 * Ready-made space blocks — standard rooms, suites, cores, outdoor spaces and
 * whole home kits that anyone can drag onto a plan. Blocks are *data*: placing
 * one runs normal model operations (walls only where missing, doors, windows,
 * furniture), so a dropped block is as editable as anything drawn by hand.
 *
 * Dimensions are wall centre-lines in feet (converted on placement) and sized
 * to pass the bundled residential room standards.
 */
import type { RoomFunction, SiteFeatureKind, DoorKind } from '../model/types';

export type Side = 'n' | 's' | 'e' | 'w';
export type BlockCategory = 'kits' | 'bedrooms' | 'bathrooms' | 'kitchens' | 'living' | 'work' | 'utility' | 'circulation' | 'parking' | 'outdoor' | 'garden';

export interface ItemSpec { asset: string; side: Side | 'center'; along?: number; gap?: number; rot?: number }

export interface BlockPart {
  key: string;
  name: string;
  fn: RoomFunction;
  x: number; y: number; w: number; h: number;
  /** Edges that are open (parapet / railing height) instead of full walls. */
  open?: Side[];
  stair?: 'U' | 'straight' | 'L';
  /** Explicit furniture; when absent the room is furnished automatically from its function. */
  items?: ItemSpec[];
  furnish?: boolean;
}

export interface BlockDoor { a: string; b: string | Side; kind?: DoorKind; width?: number }
export interface BlockSite { kind: SiteFeatureKind; name: string; x: number; y: number; w: number; h: number; material: string; cars?: number }
export interface BlockProp { asset: string; x: number; y: number; rot?: number; variant?: string }

export interface BlockSize {
  id: 'S' | 'M' | 'L';
  label: string;
  /** Footprint in feet (for kits: the plot the kit is designed for). */
  w: number;
  d: number;
  fits: string;
  parts: BlockPart[];
  doors?: BlockDoor[];
  site?: BlockSite[];
  props?: BlockProp[];
}

export interface BlockDef {
  id: string;
  name: string;
  category: BlockCategory;
  description: string;
  /** Part that connects to the neighbouring room when dropped (default: first part). */
  entry?: string;
  /** Door used to connect to the neighbour. */
  entryDoor?: DoorKind;
  /** Site-only blocks (pools, parking, lawns) — placed on the ground level, outside the building. */
  siteOnly?: boolean;
  /** Whole-home kits are generated by the layout engine for the given plot. */
  kit?: { bedrooms: number; pooja?: boolean; study?: boolean; powder?: boolean };
  sizes: BlockSize[];
  keywords: string[];
}

