const P = (key: string, name: string, fn: RoomFunction, x: number, y: number, w: number, h: number, extra: Partial<BlockPart> = {}): BlockPart => ({ key, name, fn, x, y, w, h, ...extra });
const one = (name: string, fn: RoomFunction, w: number, d: number, extra: Partial<BlockPart> = {}) => [P('room', name, fn, 0, 0, w, d, extra)];

const LUX_BATH: ItemSpec[] = [{ asset: 'vanity', side: 's', along: 0.15 }, { asset: 'wc', side: 's', along: 0.85 }, { asset: 'bathtub', side: 'n', along: 0.35 }, { asset: 'shower', side: 'e', along: 0.95 }];

type FrontCol = [string, string, RoomFunction, number] | [string, string, RoomFunction, number, number, string, string, RoomFunction];

/**
 * Whole-home kit on the classic residential diagram: a public band at the
 * front (living, dining, kitchen …), a spine corridor, and bedroom suites
 * (bedroom + bath + dressing) at the back. Every room meets the room standards.
 */
function homeKit(W: number, frontD: number, front: FrontCol[], spine: number, suites: number, suiteW: number, bedD: number, bathD: number): Pick<BlockSize, 'parts' | 'doors'> {
  const parts: BlockPart[] = [];
  const doors: BlockDoor[] = [{ a: 'liv', b: 's', kind: 'pivot', width: 1200 }];
  let x = 0;
  for (const col of front) {
    const [key, name, fn, w] = col;
    // The last column takes whatever width remains, so the band always tiles exactly.
    const width = col === front[front.length - 1] ? W - x : w;
    if (col.length === 8) {
      const [, , , , h1, key2, name2, fn2] = col;
      parts.push(P(key, name, fn, x, 0, width, h1), P(key2, name2, fn2, x, h1, width, frontD - h1));
    } else parts.push(P(key, name, fn, x, 0, width, frontD));
    x += width;
  }
  parts.push(P('spine', 'Passage', 'corridor', 0, frontD, W, spine));
  const y0 = frontD + spine;
  const half = suiteW / 2;
  for (let i = 0; i < suites; i++) {
    const sx = i * suiteW;
    const sw = i === suites - 1 ? W - sx : suiteW;
    const master = i === 0;
    const bed = master ? 'Master Bedroom' : `Bedroom ${i + 1}`;
    parts.push(P(`bed${i}`, bed, master ? 'master_bedroom' : 'bedroom', sx, y0, sw, bedD));
    parts.push(P(`bath${i}`, master ? 'Master Bath' : `Bath ${i + 1}`, 'bathroom', sx, y0 + bedD, half, bathD));
    parts.push(P(`dr${i}`, master ? 'Walk-in Wardrobe' : `Dressing ${i + 1}`, 'walkin', sx + half, y0 + bedD, sw - half, bathD));
    doors.push({ a: `bed${i}`, b: 'spine' }, { a: `bath${i}`, b: `bed${i}` }, { a: `dr${i}`, b: `bed${i}`, kind: 'opening', width: 800 });
  }
  const keys = new Set(parts.map((p) => p.key));
  doors.push({ a: 'spine', b: 'liv', kind: 'opening', width: 1100 });
  if (keys.has('din')) doors.push({ a: 'din', b: 'liv', kind: 'opening', width: 1800 });
  if (keys.has('kit')) doors.push({ a: 'kit', b: 'din' });
  if (keys.has('ut')) doors.push({ a: 'ut', b: 'kit' });
  if (keys.has('st')) doors.push({ a: 'st', b: 'kit', kind: 'opening', width: 900 });
  if (keys.has('pj')) doors.push({ a: 'pj', b: 'liv' });
  if (keys.has('pw')) doors.push({ a: 'pw', b: 'spine' });
  return { parts, doors };
}

/**
 * Narrow-plot kit: living across the front, dining + kitchen, then a central
 * passage with a bedroom + bath on each side (every bedroom keeps an outside
 * wall for daylight) and, optionally, a full-width master suite at the back.
 */
function narrowKit(W: number, livD: number, dinW: number, midD: number, colW: number, bedD: number, bathD: number, master?: { bedD: number; bathD: number }): Pick<BlockSize, 'parts' | 'doors'> {
  const parts: BlockPart[] = [P('liv', 'Living Room', 'living', 0, 0, W, livD), P('din', 'Dining', 'dining', 0, livD, dinW, midD), P('kit', 'Kitchen', 'kitchen', dinW, livD, W - dinW, midD)];
  const y0 = livD + midD;
  const depth = bedD + bathD;
  parts.push(P('spine', 'Passage', 'corridor', colW, y0, W - 2 * colW, depth));
  const doors: BlockDoor[] = [{ a: 'liv', b: 's', kind: 'pivot', width: 1200 }, { a: 'din', b: 'liv', kind: 'opening', width: 1800 }, { a: 'kit', b: 'din' }, { a: 'spine', b: 'din', kind: 'opening', width: 1000 }];
  [0, W - colW].forEach((x, i) => {
    parts.push(P(`bed${i}`, `Bedroom ${i + 1}`, 'bedroom', x, y0, colW, bedD), P(`bath${i}`, `Bath ${i + 1}`, 'bathroom', x, y0 + bedD, colW, bathD));
    doors.push({ a: `bed${i}`, b: 'spine' }, { a: `bath${i}`, b: `bed${i}` });
  });
  if (master) {
    const ym = y0 + depth;
    parts.push(P('mbed', 'Master Bedroom', 'master_bedroom', 0, ym, W, master.bedD), P('mbath', 'Master Bath', 'bathroom', 0, ym + master.bedD, W / 2, master.bathD), P('mwi', 'Walk-in Wardrobe', 'walkin', W / 2, ym + master.bedD, W / 2, master.bathD));
    doors.push({ a: 'mbed', b: 'spine' }, { a: 'mbath', b: 'mbed' }, { a: 'mwi', b: 'mbed', kind: 'opening', width: 800 });
  }
  return { parts, doors };
}

