export const BLOCK_BY_ID: Record<string, BlockDef> = Object.fromEntries(BLOCKS.map((b) => [b.id, b]));

export function blockSize(def: BlockDef, sizeId?: string): BlockSize {
  return def.sizes.find((s) => s.id === sizeId) ?? def.sizes[Math.min(1, def.sizes.length - 1)];
}

/** Search blocks by plain words ("attached bathroom", "pooja", "2bhk"). */
export function searchBlocks(q: string): BlockDef[] {
  const t = q.trim().toLowerCase();
  if (!t) return BLOCKS;
  const STOP = new Set(['a', 'an', 'the', 'for', 'with', 'and', 'of', 'to', 'my', 'in', 'on', 'room', 'space']);
  const words = t.split(/[\s,]+/).filter((w) => w && !STOP.has(w) && !/^\d+$/.test(w)).map((w) => w.replace(/s$/, ''));
  return BLOCKS.map((b) => {
    const key = `${b.name} ${b.keywords.join(' ')}`.toLowerCase();
    const desc = b.description.toLowerCase();
    // Name and keyword hits count double; descriptions only break ties.
    const score = words.reduce((s, w) => s + (key.includes(w) ? 2 : desc.includes(w) ? 0.5 : 0), 0) + (b.name.toLowerCase().includes(t) ? 3 : 0) + (b.name.toLowerCase().startsWith(t) ? 1 : 0);
    return { b, score };
  }).filter((x) => x.score >= 1).sort((a, b) => b.score - a.score).map((x) => x.b);
}
